{"name":"CheckRainAndHumidityThenSetDehumidifier","cron":"","period":0,"code":"rain = (#RainSensor).rainsensor_rain
humidity = (#HumiditySensor).humiditysensor_humidity
delay(1 HOUR)
new_humidity = (#HumiditySensor).humiditysensor_humidity
if (rain == true and (new_humidity >= 80)) {
    (#Dehumidifier).dehumidifier_setdehumidifiermode("drying")
    (#Speaker).speaker_speak("비가 오고 습도가 높습니다")
}"}

{"name":"AdjustAirConditionerBasedOnTemperature","cron":"","period":1800000,"code":"prev_temp := (#TemperatureSensor).temperaturesensor_temperature
curr_temp = (#TemperatureSensor).temperaturesensor_temperature
if (prev_temp < 20 and curr_temp >= 20) {
    (#AirConditioner).airconditioner_setairconditionermode("auto")
} else if (prev_temp >= 20 and curr_temp >= 30) {
    (#AirConditioner).airconditioner_setairconditionermode("cool")
}
prev_temp = curr_temp"}

